const CACHE = "xlfx-__VER__";
const FILES = __FILES__;
self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => encodeURI(f)))).then(() => self.skipWaiting()));
});
